/* Bulk liquids Citrix runtime v10.3.2.
 * Inherited from the verified v10.2.4 FCL Citrix export runtime.
 * Coordinates and input/route/clipboard helpers are unchanged. The only added
 * coordinate, cargo volume [365,536], is the existing LCL cargo coordinate.
 * Bulk-specific RunQuote clears optional cargo and skips an empty Incoterm.
 * Generated quotation and metadata are supplied at runtime, not stored here.
 */
(() => {
  'use strict';
  const template = [
    "#Requires AutoHotkey v2.0",
    "#SingleInstance Force",
    "#Warn",
    "",
    "; Generated by BLU Auto Quote v10.3.2 - Bulk liquids - BLU Citrix",
    "; BLU_AUTOMATION_MODE: CITRIX",
    "@@METADATA@@",
    "",
    "SPEED_PERCENT := @@SPEED@@",
    "",
    "; Optional tray icon when the ICO is next to the generated script.",
    "if FileExist(A_ScriptDir \"\\blu_prod_20260831114214.ico\")",
    "  try TraySetIcon(A_ScriptDir \"\\blu_prod_20260831114214.ico\")",
    "",
    "SetTitleMatchMode 2",
    "CoordMode \"Mouse\", \"Screen\"",
    "SendMode \"Event\"",
    "SetKeyDelay Round(25 * 100 / SPEED_PERCENT), Round(20 * 100 / SPEED_PERCENT)",
    "SetMouseDelay 40",
    "",
    "BLU_WINDOW := \"BLU ahk_exe wfica32.exe\"",
    "CLICK_DELAY := 80",
    "FIELD_DELAY := 120",
    "MENU_KEY_DELAY := 180",
    "MENU_ENTER_DELAY := 900",
    "SUPPLIER_ENTER_DELAY := 700",
    "MENU_AFTER_DELAY := 250",
    "ROW_DELAY := 1100",
    "TAB_DELAY := 900",
    "",
    "Running := false",
    "SavedClipboard := \"\"",
    "",
    "C := Map(",
    "  \"Project\", [383, 231],",
    "  \"Internal comment\", [383, 255],",
    "  \"client\", [382, 313],",
    "  \"address\", [385, 346],",
    "  \"Attention to\", [376, 602],",
    "  \"Subject\", [384, 649],",
    "  \"Salution\", [385, 671],",
    "  \"Cover letter\", [396, 698],",
    "  \"Display costs\", [374, 738],",
    "  \"YearMonth\", [364, 763],",
    "  \"Sales operator\", [365, 789],",
    "  \"inquiry type\", [839, 741],",
    "  \"target currency\", [1026, 743],",
    "  \"events target currency\", [1117, 818],",
    "  \"Valid to date\", [1019, 288],",
    "  \"cargo tab\", [293, 204],",
    "  \"add equipment\", [982, 235],",
    "  \"equipment quantity\", [365, 365],",
    "  \"kind of equipment\", [364, 392],",
    "  \"gross weight\", [380, 510],",
    "  \"cargo volume\", [365, 536],",
    "  \"details tab\", [338, 202],",
    "  \"description of goods\", [380, 664],",
    "  \"create new detail\", [969, 235],",
    "  \"detail subtitle\", [367, 356],",
    "  \"detail short description\", [368, 385],",
    "  \"plor loc code\", [490, 491],",
    "  \"polout loc code\", [488, 507],",
    "  \"podin loc code\", [495, 525],",
    "  \"plod loc code\", [497, 545],",
    "  \"plor mot\", [817, 488],",
    "  \"polout/podin mot\", [790, 504],",
    "  \"plod mot\", [790, 542],",
    "  \"podin mot\", [790, 522],",
    "  \"podin/plod mot\", [790, 522],",
    "  \"transit time\", [367, 758],",
    "  \"including\", [1281, 466],",
    "  \"excluding\", [1275, 549],",
    "  \"subject to\", [1281, 632],",
    "  \"terms of payment days\", [1286, 707],",
    "  \"service type\", [1296, 758],",
    "  \"incoterm\", [1296, 783],",
    "  \"incoterm location\", [1294, 807],",
    "  \"scroll point1\", [1905, 393],",
    "  \"scroll point2\", [1903, 686],",
    "  \"add new charge\", [966, 250],",
    "  \"charge type\", [430, 446],",
    "  \"charge description\", [431, 469],",
    "  \"charge buying rate\", [776, 594],",
    "  \"buying rate currency\", [890, 593],",
    "  \"supplier\", [1009, 593],",
    "  \"charge selling rate\", [723, 517],",
    "  \"selling rate currency\", [892, 444],",
    "  \"charge per\", [737, 542],",
    "  \"charge quantity\", [888, 543],",
    "  \"charge quantity description\", [943, 543],",
    "  \"delete route point\", [983, 517],",
    "  \"charges remarks\", [880, 690]",
    ")",
    "",
    "@@QUOTE@@",
    "",
    "OnExit RestoreClipboard",
    "",
    "F8:: {",
    "  global Running",
    "  if Running",
    "    return",
    "  Running := true",
    "  try RunQuote()",
    "  catch Error as err",
    "    MsgBox \"Automation stopped with an error:`n`n\" err.Message, \"BLU Quote Automation\", \"Iconx\"",
    "  finally {",
    "    ToolTip",
    "    RestoreClipboard()",
    "    Running := false",
    "  }",
    "}",
    "",
    "F9::Pause -1",
    "Esc::ExitApp",
    "",
    "RunQuote() {",
    "  global SavedClipboard, quote, FIELD_DELAY, MENU_ENTER_DELAY",
    "  startTick := A_TickCount",
    "  CheckEnvironment()",
    "  ActivateBlu()",
    "  SavedClipboard := ClipboardAll()",
    "",
    "  ToolTip \"BLU automation: main quote fields\"",
    "  TypeField(\"Project\", quote[\"project\"], true)",
    "  TypeField(\"Internal comment\", quote[\"internalComment\"], false, true)",
    "  TypeField(\"client\", quote[\"clientCode\"], false, true)",
    "  TypeField(\"address\", StrUpper(quote[\"clientName\"]), false, true)",
    "  TypeField(\"Attention to\", quote[\"attentionTo\"])",
    "  TypeField(\"Subject\", quote[\"subject\"])",
    "  TypeField(\"Salution\", quote[\"salutation\"])",
    "  TypeField(\"Cover letter\", quote[\"coverLetter\"])",
    "",
    "  ClickField(\"Display costs\")",
    "  WaitV974(200)",
    "  TypeTextV974(\"c\")",
    "  WaitV974(180)",
    "  TypeTextV974(\"c\")",
    "  WaitV974(180)",
    "  FieldReadyDelayV974(\"Display costs\")",
    "  Send \"{Enter}\"",
    "  WaitV974(FIELD_DELAY)",
    "",
    "  TypeField(\"YearMonth\", FormatTime(, \"yyMM\"))",
    "  TypeField(\"Sales operator\", quote[\"salesOperator\"])",
    "  SelectField(\"inquiry type\", \"f\")",
    "  SelectField(\"target currency\", quote[\"targetCurrency\"])",
    "  ClickField(\"events target currency\")",
    "  TypeField(\"Valid to date\", quote[\"validTo\"], true)",
    "",
    "  ToolTip \"BLU automation: equipment\"",
    "  ClickField(\"cargo tab\", TAB_DELAY)",
    "  for equipment in quote[\"cargoEquipment\"] {",
    "    ClickField(\"add equipment\", ROW_DELAY)",
    "    TypeField(\"equipment quantity\", equipment[\"quantity\"], false, true)",
    "    SelectField(\"kind of equipment\", equipment[\"equipmentSearch\"])",
    "    TypeField(\"gross weight\", quote[\"grossWeight\"], false, true)",
    "    TypeField(\"cargo volume\", BulkDecimal(quote[\"volume\"]), false, true)",
    "    TypeField(\"description of goods\", quote[\"cargoDescription\"], false, true)",
    "  }",
    "",
    "  ToolTip \"BLU automation: details and charges\"",
    "  ClickField(\"details tab\", TAB_DELAY)",
    "  for index, detail in quote[\"details\"] {",
    "    if index > 1",
    "      ScrollDetailUp()",
    "    ClickField(\"create new detail\", ROW_DELAY)",
    "    TypeField(\"detail subtitle\", detail[\"subtitle\"])",
    "    PasteField(\"detail short description\", StrUpper(quote[\"clientName\"]), true)",
    "    ConfigurePhysicalRoute(detail)",
    "    TypeField(\"transit time\", detail[\"transitTime\"])",
    "    TypeField(\"including\", detail[\"including\"], false, true)",
    "    TypeField(\"excluding\", detail[\"excluding\"], false, true)",
    "    PasteField(\"subject to\", quote[\"subjectTo\"], true)",
    "    TypeField(\"terms of payment days\", quote[\"paymentDays\"])",
    "    SelectField(\"service type\", \"f\")",
    "    if detail[\"incoterm\"] != \"\" {",
    "      SelectField(\"incoterm\", detail[\"incoterm\"])",
    "      TypeField(\"incoterm location\", detail[\"incotermLocation\"], false, true)",
    "    } else {",
    "      TypeField(\"incoterm\", \"\", false, true)",
    "      TypeField(\"incoterm location\", \"\", false, true)",
    "    }",
    "    ScrollDetailDown()",
    "    for charge in detail[\"charges\"]",
    "      FillCharge(charge)",
    "    PasteRemarksField(detail[\"remarks\"])",
    "  }",
    "",
    "  ToolTip",
    "  RestoreClipboard()",
    "  elapsed := FormatElapsed(A_TickCount - startTick)",
    "  resultText := \"The BLU quote has been entered.\"",
    "  MsgBox resultText \"`n`nTime: \" elapsed \"`n`nReview the quote before sending it.\", \"BLU Quote Automation\", \"Iconi\"",
    "}",
    "",
    "ConfigurePhysicalRoute(detail) {",
    "  global MENU_ENTER_DELAY",
    "  pointFields := [\"plor loc code\", \"polout loc code\", \"podin loc code\", \"plod loc code\"]",
    "  pointCodes := [detail[\"routeCollectionCode\"], detail[\"routePolCode\"], detail[\"routePodCode\"], detail[\"routeDeliveryCode\"]]",
    "  pointEnabled := [detail[\"hasCollection\"], detail[\"hasPol\"], detail[\"hasPod\"], detail[\"hasDelivery\"]]",
    "  ; Keep original coordinates until ALL locations and modes are entered.",
    "  for index, fieldName in pointFields {",
    "    if pointEnabled[index] && pointCodes[index] != \"\"",
    "      SelectField(fieldName, pointCodes[index])",
    "  }",
    "  ; POLout and PODin share the vessel selection. Do not overwrite PODin with truck.",
    "  if detail[\"hasPol\"] && detail[\"hasPod\"]",
    "    DoubleSelectField(\"polout/podin mot\", \"v\")",
    "  else if detail[\"hasCollection\"] && detail[\"hasPod\"]",
    "    DoubleSelectField(\"podin mot\", \"v\")",
    "  if detail[\"hasCollection\"] && detail[\"hasPol\"]",
    "    DoubleSelectField(\"plor mot\", \"t\")",
    "  if detail[\"hasDelivery\"]",
    "    DoubleSelectField(\"plod mot\", detail[\"deliveryMode\"])",
    "  ; Delete bottom-to-top only after entry; remaining original rows do not move.",
    "  Loop 4 {",
    "    index := 5 - A_Index",
    "    if !pointEnabled[index] {",
    "      ClickField(pointFields[index])",
    "      ClickField(\"delete route point\", MENU_ENTER_DELAY)",
    "    }",
    "  }",
    "}",
    "",
    "PhysicalRouteMode(fromKind, toKind, deliveryMode) {",
    "  if toKind = \"delivery\"",
    "    return deliveryMode",
    "  if fromKind = \"collection\" && toKind = \"pol\"",
    "    return \"t\"",
    "  if toKind = \"pod\" || fromKind = \"pol\"",
    "    return \"v\"",
    "  return \"t\"",
    "}",
    "",
    "WaitV974(milliseconds) {",
    "  global SPEED_PERCENT",
    "  Sleep Max(1, Round(milliseconds * 100 / SPEED_PERCENT))",
    "}",
    "",
    "FieldReadyDelayV974(name) {",
    "  key := StrLower(name)",
    "  if InStr(key, \"currency\") || InStr(key, \"supplier\") || key = \"display costs\" || key = \"inquiry type\" || key = \"sales operator\" || key = \"incoterm\" || key = \"service type\"",
    "    WaitV974(500)",
    "}",
    "",
    "TypeTextV974(value, forceTyping := false) {",
    "  global SPEED_PERCENT",
    "  if SPEED_PERCENT = 100 && !forceTyping {",
    "    SendText String(value)",
    "    return",
    "  }",
    "  ; SendText supports Unicode. Treat CRLF as one deliberate line break.",
    "  value := StrReplace(String(value), \"`r`n\", \"`n\")",
    "  for character in StrSplit(value) {",
    "    if character = \"`r\"",
    "      continue",
    "    if character = \"`n\"",
    "      Send \"{Enter}\"",
    "    else",
    "      SendText character",
    "    WaitV974(25)",
    "  }",
    "}",
    "",
    "FormatElapsed(milliseconds) {",
    "  totalSeconds := Floor(milliseconds / 1000)",
    "  minutes := Floor(totalSeconds / 60)",
    "  seconds := Mod(totalSeconds, 60)",
    "  return minutes > 0 ? minutes \" min \" seconds \" sec\" : seconds \" sec\"",
    "}",
    "",
    "CheckEnvironment() {",
    "  if A_ScreenWidth != 1920 || A_ScreenHeight != 1080",
    "    throw Error(\"This script requires 1920 x 1080. Current resolution: \" A_ScreenWidth \" x \" A_ScreenHeight)",
    "  if A_ScreenDPI != 96",
    "    throw Error(\"This script requires Windows scaling 100% (96 DPI). Current DPI: \" A_ScreenDPI)",
    "}",
    "",
    "ActivateBlu() {",
    "  global BLU_WINDOW",
    "  if !WinExist(BLU_WINDOW)",
    "    throw Error(\"Could not find the BLU Citrix window (wfica32.exe).\")",
    "  WinActivate BLU_WINDOW",
    "  WinMaximize BLU_WINDOW",
    "  if !WinWaitActive(BLU_WINDOW, , 6)",
    "    throw Error(\"BLU could not be activated.\")",
    "  WaitV974(600)",
    "}",
    "",
    "ClickField(name, wait := 0) {",
    "  global C, CLICK_DELAY",
    "  xy := C[name]",
    "  Click xy[1], xy[2]",
    "  WaitV974(wait > 0 ? wait : CLICK_DELAY)",
    "}",
    "",
    "SlowType(value) {",
    "  global MENU_KEY_DELAY",
    "  for character in StrSplit(String(value)) {",
    "    SendText character",
    "    WaitV974(MENU_KEY_DELAY)",
    "  }",
    "}",
    "",
    "TypeField(name, value, pressEnter := false, clearFirst := false) {",
    "  global FIELD_DELAY, MENU_ENTER_DELAY, MENU_AFTER_DELAY",
    "  if StrLower(name) = \"gross weight\"",
    "    value := StrReplace(String(value), \".\", \",\")",
    "  ClickField(name)",
    "  WaitV974(200)",
    "  if clearFirst {",
    "    Send \"^a\"",
    "    WaitV974(80)",
    "    Send \"{Backspace}\"",
    "    WaitV974(80)",
    "  }",
    "  if pressEnter",
    "    SlowType(value)",
    "  else if StrLower(name) = \"including\" || StrLower(name) = \"excluding\"",
    "    TypeTextV974(value, true)",
    "  else if RegExMatch(String(value), \"[^\\x00-\\x7F]\")",
    "    PasteCurrent(value)",
    "  else",
    "    TypeTextV974(value)",
    "  FieldReadyDelayV974(name)",
    "  if pressEnter {",
    "    WaitV974(MENU_ENTER_DELAY)",
    "    Send \"{Enter}\"",
    "    WaitV974(MENU_AFTER_DELAY)",
    "  } else",
    "    WaitV974(FIELD_DELAY)",
    "}",
    "",
    "PasteCurrent(value, clearFirst := false) {",
    "  global FIELD_DELAY, SPEED_PERCENT",
    "  value := String(value)",
    "  if value = \"\" {",
    "    if clearFirst {",
    "      Send \"^a\"",
    "      WaitV974(100)",
    "      Send \"{Backspace}\"",
    "      WaitV974(FIELD_DELAY)",
    "    }",
    "    return",
    "  }",
    "  if SPEED_PERCENT < 100 {",
    "    if clearFirst {",
    "      Send \"^a\"",
    "      WaitV974(100)",
    "      Send \"{Backspace}\"",
    "      WaitV974(100)",
    "    }",
    "    TypeTextV974(value, true)",
    "    WaitV974(FIELD_DELAY + 250)",
    "    return",
    "  }",
    "  ; Prepare and verify fresh clipboard text BEFORE clearing the destination.",
    "  ready := false",
    "  Loop 3 {",
    "    try {",
    "      A_Clipboard := \"\"",
    "      A_Clipboard := value",
    "      if ClipWait(2) && StrCompare(A_Clipboard, value, true) = 0 {",
    "        ready := true",
    "        break",
    "      }",
    "    }",
    "    WaitV974(150)",
    "  }",
    "  if !ready",
    "    throw Error(\"Clipboard did not become ready with the expected text. No paste was attempted.\")",
    "  if clearFirst {",
    "    Send \"^a\"",
    "    WaitV974(120)",
    "    Send \"{Backspace}\"",
    "    WaitV974(120)",
    "  }",
    "  WaitV974(350)",
    "  ; A single paste only: blindly retrying risks duplicate quotation text.",
    "  SendEvent \"^v\"",
    "  WaitV974(FIELD_DELAY + 450)",
    "}",
    "",
    "PasteField(name, value, clearFirst := false) {",
    "  ClickField(name, 200)",
    "  WaitV974(200)",
    "  PasteCurrent(value, clearFirst)",
    "}",
    "",
    "PasteRemarksField(value) {",
    "  global FIELD_DELAY",
    "  ClickField(\"charges remarks\", 350)",
    "  ClickField(\"charges remarks\", 180)",
    "  WaitV974(200)",
    "  PasteCurrent(value, true)",
    "  WaitV974(FIELD_DELAY + 350)",
    "  Send \"{Tab}\"",
    "  WaitV974(200)",
    "}",
    "",
    "SelectField(name, value, arrowOffset := 0) {",
    "  global MENU_ENTER_DELAY, MENU_AFTER_DELAY",
    "  if IsRouteCodeV1023(name) {",
    "    TypeRouteCodeV1023(name, value)",
    "    return",
    "  }",
    "  ClickField(name)",
    "  WaitV974(200)",
    "  SlowType(value)",
    "  FieldReadyDelayV974(name)",
    "  WaitV974(MENU_ENTER_DELAY)",
    "  if arrowOffset != 0 {",
    "    key := arrowOffset > 0 ? \"{Down}\" : \"{Up}\"",
    "    Loop Abs(arrowOffset) {",
    "      Send key",
    "      WaitV974(350)",
    "    }",
    "  }",
    "  Send \"{Enter}\"",
    "  WaitV974(MENU_AFTER_DELAY)",
    "}",
    "",
    "SelectSupplierField(value, arrowOffset := 0) {",
    "  global SUPPLIER_ENTER_DELAY, MENU_AFTER_DELAY",
    "  ClickField(\"supplier\")",
    "  WaitV974(200)",
    "  TypeTextV974(String(value))",
    "  FieldReadyDelayV974(\"supplier\")",
    "  WaitV974(SUPPLIER_ENTER_DELAY)",
    "  if arrowOffset != 0 {",
    "    key := arrowOffset > 0 ? \"{Down}\" : \"{Up}\"",
    "    Loop Abs(arrowOffset) {",
    "      Send key",
    "      WaitV974(200)",
    "    }",
    "  }",
    "  Send \"{Enter}\"",
    "  WaitV974(MENU_AFTER_DELAY)",
    "}",
    "",
    "TypePriceField(name, value) {",
    "  TypeField(name, StrReplace(String(value), \".\", \",\"))",
    "}",
    "",
    "DoubleSelectField(name, value) {",
    "  global C, MENU_ENTER_DELAY, MENU_AFTER_DELAY",
    "  xy := C[name]",
    "  Click xy[1], xy[2]",
    "  WaitV974(90)",
    "  Click xy[1], xy[2]",
    "  WaitV974(220)",
    "  WaitV974(200)",
    "  SlowType(value)",
    "  FieldReadyDelayV974(name)",
    "  WaitV974(MENU_ENTER_DELAY)",
    "  Send \"{Enter}\"",
    "  WaitV974(MENU_AFTER_DELAY)",
    "}",
    "",
    "TypeDetailDescription(clientName, basisText) {",
    "  global FIELD_DELAY",
    "  ClickField(\"detail short description\", 250)",
    "  WaitV974(200)",
    "  Send \"^a\"",
    "  WaitV974(100)",
    "  Send \"{Backspace}\"",
    "  PasteCurrent(StrUpper(clientName))",
    "  WaitV974(250)",
    "  Send \"{Enter}\"",
    "  WaitV974(350)",
    "  PasteCurrent(basisText)",
    "  WaitV974(FIELD_DELAY + 200)",
    "  Send \"{Tab}\"",
    "  WaitV974(180)",
    "}",
    "",
    "ScrollDetailDown() {",
    "  global C, TAB_DELAY",
    "  a := C[\"scroll point1\"], b := C[\"scroll point2\"]",
    "  MouseClickDrag \"Left\", a[1], a[2], b[1], b[2], 8",
    "  WaitV974(TAB_DELAY)",
    "}",
    "",
    "ScrollDetailUp() {",
    "  global C, TAB_DELAY",
    "  a := C[\"scroll point1\"], b := C[\"scroll point2\"]",
    "  MouseClickDrag \"Left\", b[1], b[2], a[1], a[2], 8",
    "  WaitV974(TAB_DELAY)",
    "}",
    "",
    "FillCharge(charge) {",
    "  global ROW_DELAY",
    "  ClickField(\"add new charge\", ROW_DELAY)",
    "  SelectField(\"charge type\", charge[\"type\"])",
    "  if charge[\"description\"] != \"\"",
    "    PasteField(\"charge description\", charge[\"description\"], true)",
    "  if charge[\"buyRate\"] != \"\"",
    "    TypePriceField(\"charge buying rate\", charge[\"buyRate\"])",
    "  if charge[\"buyCurrency\"] != \"\"",
    "    SelectField(\"buying rate currency\", StrLower(charge[\"buyCurrency\"]))",
    "  if charge[\"supplier\"] != \"\"",
    "    SelectSupplierField(charge[\"supplier\"], charge.Has(\"supplierArrow\") ? charge[\"supplierArrow\"] : 0)",
    "  TypePriceField(\"charge selling rate\", charge[\"sellingRate\"])",
    "  SelectField(\"selling rate currency\", StrLower(charge[\"sellingCurrency\"]))",
    "  SelectField(\"charge per\", \"q\")",
    "  TypeField(\"charge quantity\", charge[\"quantity\"])",
    "  TypeField(\"charge quantity description\", charge[\"quantityDescription\"])",
    "}",
    "",
    "ClickInWindow(title, x, y, wait := 250) {",
    "  if title != \"\" {",
    "    target := title \" ahk_exe wfica32.exe\"",
    "    if WinExist(target) {",
    "      WinActivate target",
    "      WinWaitActive target, , 5",
    "    }",
    "  }",
    "  Click x, y",
    "  WaitV974(wait)",
    "}",
    "",
    "RestoreClipboard(*) {",
    "  global SavedClipboard",
    "  if IsObject(SavedClipboard) {",
    "    A_Clipboard := SavedClipboard",
    "    SavedClipboard := \"\"",
    "  }",
    "}",
    "",
    "IsRouteCodeV1023(name) {",
    "  key := StrLower(name)",
    "  return key = \"plor loc code\" || key = \"polout loc code\" || key = \"podin loc code\" || key = \"plod loc code\"",
    "}",
    "",
    "TypeRouteCodeV1023(name, value) {",
    "  global MENU_AFTER_DELAY",
    "  ; 500 ms after click, 2 seconds across five letters, then 1000 ms before Enter.",
    "  ; Dedicated route timing replaces the ordinary select/menu waits.",
    "  ClickField(name, 500)",
    "  Send \"^a\"",
    "  for index, character in StrSplit(String(value)) {",
    "    if index > 1",
    "      WaitV974(500)",
    "    SendText character",
    "  }",
    "  WaitV974(1000)",
    "  Send \"{Enter}\"",
    "  WaitV974(MENU_AFTER_DELAY)",
    "}",
    "",
    "BulkDecimal(value) {",
    "  return StrReplace(String(value), \".\", \",\")",
    "}",
    ""
  ].join('\n');
  window.BLU_BULK_CITRIX_V1030 = (quoteBlock, metadata, speed) => template
    .replace('@@METADATA@@', () => metadata)
    .replace('@@QUOTE@@', () => quoteBlock)
    .replace('@@SPEED@@', () => String(speed));
})();
